import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const codexSessions = "/Users/vincet/.codex/sessions";
const archiveRoot = "/Users/vincet/Documents/ttgame/codex_thread_archive";
const rawRoot = path.join(archiveRoot, "raw");
const readableRoot = path.join(archiveRoot, "readable");
const readmePath = path.join(archiveRoot, "README.md");

function sh(cmd, args) {
  return execFileSync(cmd, args, { encoding: "utf8" });
}

function listRollouts(root) {
  if (!fs.existsSync(root)) return [];
  return sh("find", [root, "-type", "f", "-name", "rollout-*.jsonl"])
    .trim()
    .split(/\n/)
    .filter(Boolean)
    .sort();
}

function relSessionPath(file) {
  return path.relative(codexSessions, file);
}

function readJsonl(file) {
  return fs.readFileSync(file, "utf8")
    .split(/\n/)
    .filter(Boolean)
    .map((line) => {
      try {
        return JSON.parse(line);
      } catch {
        return null;
      }
    })
    .filter(Boolean);
}

function textFromContent(content = []) {
  return content.map((item) => item.text || "").join("");
}

function redactSecretsText(text) {
  return text
    .replace(/LTAI[A-Za-z0-9]{12,}/g, "[REDACTED_ALIBABA_ACCESS_KEY_ID]")
    .replace(/(access_key_id["'\s:=]+)[A-Za-z0-9_-]{12,}/gi, "$1[REDACTED_ACCESS_KEY_ID]")
    .replace(/(accessKeyId["'\s:=]+)[A-Za-z0-9_-]{12,}/g, "$1[REDACTED_ACCESS_KEY_ID]");
}

function writeIfChanged(file, content) {
  content = redactSecretsText(content);
  if (fs.existsSync(file) && fs.readFileSync(file, "utf8") === content) {
    return false;
  }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content, "utf8");
  return true;
}

function copyIfChanged(source, target) {
  const sourceContent = redactSecretsText(fs.readFileSync(source, "utf8"));
  if (fs.existsSync(target) && fs.readFileSync(target, "utf8") === sourceContent) {
    return false;
  }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, sourceContent, "utf8");
  return true;
}

function toReadableMarkdown(rawFile) {
  const rows = readJsonl(rawFile);
  let markdown = `# ${path.basename(rawFile)}\n\n`;

  for (const row of rows) {
    const payload = row.payload || {};

    if (row.type === "session_meta") {
      markdown += "## [SESSION_META]\n";
      markdown += `- id: ${payload.id || ""}\n`;
      markdown += `- timestamp: ${payload.timestamp || ""}\n`;
      markdown += `- cwd: ${payload.cwd || ""}\n`;
      markdown += `- cli_version: ${payload.cli_version || ""}\n\n`;
      continue;
    }

    if (row.type === "event_msg" && payload.type === "user_message" && payload.message) {
      markdown += "## [USER]\n";
      markdown += `${payload.message.trim()}\n\n`;
      continue;
    }

    if (row.type === "event_msg" && payload.type === "agent_message" && payload.message) {
      markdown += "## [ASSISTANT]\n";
      markdown += `${payload.message.trim()}\n\n`;
      continue;
    }

    if (row.type === "response_item" && payload.type === "message") {
      const text = textFromContent(payload.content).trim();
      if (!text) continue;
      markdown += `## [${String(payload.role || "message").toUpperCase()}]\n`;
      markdown += `${text}\n\n`;
    }
  }

  return markdown;
}

function getLastSession(files) {
  let latest = null;
  for (const file of files) {
    const rows = readJsonl(file);
    const metaRow = rows.find((row) => row.type === "session_meta");
    const timestamp = metaRow?.payload?.timestamp || "";
    if (!latest || timestamp > latest.timestamp) {
      latest = { file, timestamp };
    }
  }
  return latest;
}

const sessionFiles = listRollouts(codexSessions);
const added = [];
const updated = [];
for (const sessionFile of sessionFiles) {
  const rel = relSessionPath(sessionFile);
  const rawTarget = path.join(rawRoot, rel);
  const readableTarget = path.join(
    readableRoot,
    `${path.basename(sessionFile, ".jsonl")}.md`,
  );
  const existed = fs.existsSync(rawTarget);
  const rawChanged = copyIfChanged(sessionFile, rawTarget);
  const readableChanged = writeIfChanged(readableTarget, toReadableMarkdown(sessionFile));

  if (!existed) {
    added.push({ sessionFile, rawTarget, readableTarget });
  } else if (rawChanged || readableChanged) {
    updated.push({ sessionFile, rawTarget, readableTarget });
  }
}

const rawFiles = listRollouts(rawRoot);
const readableFiles = sh("find", [readableRoot, "-type", "f", "-name", "rollout-*.md"])
  .trim()
  .split(/\n/)
  .filter(Boolean);
const latest = getLastSession(rawFiles);

const generatedAt = new Date().toLocaleString("sv-SE", {
  timeZone: "Asia/Taipei",
  hour12: false,
}).replace("T", " ");

const readme = [
  "# Codex Thread Archive",
  "",
  `- Generated at: ${generatedAt} CST`,
  "- Source: /Users/vincet/.codex/sessions",
  `- Raw files: ${rawFiles.length}`,
  `- Readable transcripts: ${readableFiles.length}`,
  `- Latest session: ${latest ? latest.file.replace(rawRoot, codexSessions) : ""}`,
  "",
].join("\n");

fs.writeFileSync(readmePath, readme, "utf8");

console.log(JSON.stringify({
  added_count: added.length,
  updated_count: updated.length,
  raw_files: rawFiles.length,
  readable_transcripts: readableFiles.length,
  latest_session: latest ? latest.file.replace(rawRoot, codexSessions) : null,
  added,
  updated,
}, null, 2));

